//! The bundled IANA time zone database.
//!
//! `tzdata.txt` is a text table generated by `scripts/generate_tzdata.py`
//! (`just tzdata`) from a pinned release of the `tzdata` PyPI package; the
//! script's docstring documents the format, the feature tags and the rank
//! ladder. The engine embeds `tzdata.txt.z`, the same bytes deflated, and
//! inflates and parses them once on first use into a `Lazy` table
//! (`hegel-c/docs/datetime.md` §5).
//!
//! Every name the database knows, link or primary zone, is a [`Name`]
//! carrying its tags, its shrink rank and the [`Zone`] whose transitions
//! apply to it. Lookup is an exact, case-sensitive match on the name as
//! the database spells it.

use crate::control::{
    InternalError, hegel_internal_assert, hegel_internal_error, hegel_internal_unwrap,
};
use crate::sys::sync::Lazy;
use alloc::boxed::Box;
use alloc::string::{String, ToString};
use alloc::vec::Vec;
use core::ffi::CStr;

/// The deflated table; see the module docs.
const COMPRESSED_TABLE: &[u8] = include_bytes!("tzdata.txt.z");

/// The IANA release the table was generated from, such as `"2026e"`.
pub const VERSION: &str = include_str!("version.txt");

/// [`VERSION`] as a NUL-terminated C string.
pub static VERSION_CSTR: &CStr =
    match CStr::from_bytes_with_nul(concat!(include_str!("version.txt"), "\0").as_bytes()) {
        Ok(c) => c,
        Err(_) => unreachable!(),
    };

/// Upper bound on the inflated table, a few times its real size.
const MAX_TABLE_LEN: usize = 16 << 20;

/// Exclusive bound on the magnitude of every offset in the table, in
/// seconds: two days. The evaluator searches for a wall time's instants
/// within this distance of it (`native::timezone`'s `WINDOW`), so an
/// offset at or beyond it would be missed; RFC 9636 recommends that
/// offsets stay within a day.
pub const UTOFF_BOUND: i32 = 2 * 86_400;

/// A feature of a zone, computed by the generator script from the zone's
/// offsets (never from its DST flags) and its name. The script's docstring
/// defines each one.
#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Tag {
    Fixed,
    WholeHour,
    Fractional,
    Seconds,
    Dst,
    DstOther,
    Multi,
    BaseChange,
    Midnight,
    SpansMidnight,
    WholeDay,
    SameOffset,
    Undefined,
    Link,
    Legacy,
    InvertedSign,
}

impl Tag {
    /// Every tag, in the order the table lists them.
    pub const ALL: [Tag; 16] = [
        Tag::Fixed,
        Tag::WholeHour,
        Tag::Fractional,
        Tag::Seconds,
        Tag::Dst,
        Tag::DstOther,
        Tag::Multi,
        Tag::BaseChange,
        Tag::Midnight,
        Tag::SpansMidnight,
        Tag::WholeDay,
        Tag::SameOffset,
        Tag::Undefined,
        Tag::Link,
        Tag::Legacy,
        Tag::InvertedSign,
    ];

    /// The tag's name in the table.
    pub fn as_str(self) -> &'static str {
        match self {
            Tag::Fixed => "fixed",
            Tag::WholeHour => "whole_hour",
            Tag::Fractional => "fractional",
            Tag::Seconds => "seconds",
            Tag::Dst => "dst",
            Tag::DstOther => "dst_other",
            Tag::Multi => "multi",
            Tag::BaseChange => "base_change",
            Tag::Midnight => "midnight",
            Tag::SpansMidnight => "spans_midnight",
            Tag::WholeDay => "whole_day",
            Tag::SameOffset => "same_offset",
            Tag::Undefined => "undefined",
            Tag::Link => "link",
            Tag::Legacy => "legacy",
            Tag::InvertedSign => "inverted_sign",
        }
    }

    /// Inverse of [`as_str`](Self::as_str).
    pub fn from_name(name: &str) -> Option<Tag> {
        Tag::ALL.iter().copied().find(|tag| tag.as_str() == name)
    }

    fn bit(self) -> u32 {
        1 << (self as u32)
    }
}

/// A set of [`Tag`]s.
#[derive(Copy, Clone, Debug, PartialEq, Eq, Default)]
pub struct Tags(u32);

impl Tags {
    /// The empty set.
    pub const EMPTY: Tags = Tags(0);

    /// Whether `tag` is in the set.
    pub fn contains(self, tag: Tag) -> bool {
        self.0 & tag.bit() != 0
    }

    /// The set with `tag` added.
    pub fn with(self, tag: Tag) -> Tags {
        Tags(self.0 | tag.bit())
    }

    /// The number of tags in the set.
    pub fn len(self) -> usize {
        self.0.count_ones() as usize
    }

    /// Whether the set is empty.
    pub fn is_empty(self) -> bool {
        self.0 == 0
    }

    /// The tags in the set, in [`Tag::ALL`] order.
    pub fn iter(self) -> impl Iterator<Item = Tag> {
        Tag::ALL.into_iter().filter(move |&tag| self.contains(tag))
    }
}

/// A local time type: the offset and designation in force over some span
/// of a zone's history.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct LocalTimeType {
    /// Seconds east of UT.
    pub utoff: i32,
    /// The TZif `isdst` flag; informational only, as the main and
    /// rearguard data differ on it.
    pub is_dst: bool,
    /// Index into [`Zone::abbreviations`].
    pub abbreviation: usize,
}

/// An explicit transition: from `instant` on, `kind` applies.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct Transition {
    /// Unix seconds.
    pub instant: i64,
    pub kind: LocalTimeType,
}

/// The day a footer rule names within a year (RFC 9636 §3.3.1).
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum RuleDay {
    /// `Jn`: day `n` in `1..=365`, never counting February 29.
    Julian(u16),
    /// `n`: day `n` in `0..=365`, counting February 29.
    ZeroBased(u16),
    /// `Mm.w.d`: weekday `d` (0 is Sunday) of week `w` (5 is the last) of
    /// month `m`.
    MonthWeekDay { month: u8, week: u8, weekday: u8 },
}

/// When a footer rule's transition happens: `time` seconds after local
/// midnight of `day`, in the offset in force before the transition. The
/// time may be negative or exceed a day (RFC 9636 allows -167 to 167
/// hours).
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct RuleDate {
    pub day: RuleDay,
    pub time: i32,
}

/// The DST half of a footer rule.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct DstRule {
    /// Always has `is_dst` set, as the standard half never does.
    pub kind: LocalTimeType,
    /// When DST starts each year.
    pub start: RuleDate,
    /// When DST ends each year.
    pub end: RuleDate,
}

/// The POSIX TZ footer, pre-parsed: the rule in force after the last
/// explicit transition, for every later year.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct Footer {
    pub standard: LocalTimeType,
    pub dst: Option<DstRule>,
}

/// A primary zone's data.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Zone {
    pub name: String,
    pub abbreviations: Vec<String>,
    /// The type in force before the first transition.
    pub initial: LocalTimeType,
    /// Strictly ascending by instant.
    pub transitions: Vec<Transition>,
    /// `None` when the file has no footer, in which case the last
    /// transition's type (or `initial`) applies for ever after.
    pub footer: Option<Footer>,
}

/// A name the database knows, with its classification and its zone.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Name {
    pub name: String,
    /// Position on the shrink ladder: `UTC` is 0, and ranks are unique
    /// across all names.
    pub rank: u16,
    pub tags: Tags,
    /// The zone whose data applies: the name's own, or its link target.
    pub zone: &'static Zone,
}

impl Name {
    /// Whether this name is a link to [`Self::zone`] rather than its own.
    pub fn is_link(&self) -> bool {
        self.tags.contains(Tag::Link)
    }
}

struct Table {
    version: String,
    names: Vec<Name>,
}

struct ZoneRecord {
    zone: Zone,
    rank: u16,
    tags: Tags,
    has_initial: bool,
}

struct LinkRecord {
    name: String,
    primary: String,
    rank: u16,
    tags: Tags,
}

fn table() -> Result<&'static Table, InternalError> {
    static TABLE: Lazy<Result<Table, InternalError>> = Lazy::new(|| {
        let text = miniz_oxide::inflate::decompress_to_vec_zlib_with_limit(
            COMPRESSED_TABLE,
            MAX_TABLE_LEN,
        );
        let text = hegel_internal_unwrap!(text.ok(), "the bundled tzdata table does not inflate");
        let text = hegel_internal_unwrap!(
            core::str::from_utf8(&text).ok(),
            "the bundled tzdata table is not UTF-8"
        );
        parse_table(text)
    });
    TABLE.as_ref().map_err(Clone::clone)
}

/// Every name in the database, sorted by name.
pub fn names() -> Result<&'static [Name], InternalError> {
    Ok(&table()?.names)
}

/// The entry for `name`, matched exactly and case-sensitively, or `None`
/// when the database has no such name.
pub fn lookup(name: &str) -> Result<Option<&'static Name>, InternalError> {
    let names = names()?;
    Ok(names
        .binary_search_by(|entry| entry.name.as_str().cmp(name))
        .ok()
        .map(|i| &names[i]))
}

/// Parse the text table. Separate from [`table`] so tests can parse
/// malformed tables.
fn parse_table(text: &str) -> Result<Table, InternalError> {
    let mut version: Option<String> = None;
    let mut zones: Vec<ZoneRecord> = Vec::new();
    let mut links: Vec<LinkRecord> = Vec::new();
    for (index, line) in text.lines().enumerate() {
        let lineno = index + 1;
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let mut fields = line.split(' ');
        let kind = hegel_internal_unwrap!(fields.next(), "tzdata line {lineno}: empty");
        let fields: Vec<&str> = fields.collect();
        match kind {
            "V" => {
                hegel_internal_assert!(
                    version.is_none() && fields.len() == 1,
                    "tzdata line {lineno}: malformed version record"
                );
                version = Some(fields[0].to_string());
            }
            "Z" => {
                hegel_internal_assert!(
                    fields.len() == 3,
                    "tzdata line {lineno}: malformed zone record"
                );
                zones.push(ZoneRecord {
                    zone: Zone {
                        name: fields[0].to_string(),
                        abbreviations: Vec::new(),
                        initial: LocalTimeType {
                            utoff: 0,
                            is_dst: false,
                            abbreviation: 0,
                        },
                        transitions: Vec::new(),
                        footer: None,
                    },
                    rank: parse_number(fields[1], lineno)?,
                    tags: parse_tags(fields[2], lineno)?,
                    has_initial: false,
                });
            }
            "L" => {
                hegel_internal_assert!(
                    fields.len() == 4,
                    "tzdata line {lineno}: malformed link record"
                );
                links.push(LinkRecord {
                    name: fields[0].to_string(),
                    primary: fields[1].to_string(),
                    rank: parse_number(fields[2], lineno)?,
                    tags: parse_tags(fields[3], lineno)?,
                });
            }
            _ => {
                let record = hegel_internal_unwrap!(
                    zones.last_mut(),
                    "tzdata line {lineno}: {kind} record before any zone"
                );
                parse_zone_line(record, kind, &fields, lineno)?;
            }
        }
    }
    let version = hegel_internal_unwrap!(version, "tzdata table has no version record");
    for record in &zones {
        hegel_internal_assert!(
            !record.zone.abbreviations.is_empty(),
            "tzdata zone {} has no abbreviations",
            record.zone.name
        );
        hegel_internal_assert!(
            record.has_initial,
            "tzdata zone {} has no initial record",
            record.zone.name
        );
    }
    let zone_count = zones.len();
    let (zone_data, zone_meta): (Vec<Zone>, Vec<(u16, Tags)>) = zones
        .into_iter()
        .map(|record| (record.zone, (record.rank, record.tags)))
        .unzip();
    let zone_data: &'static [Zone] = Box::leak(zone_data.into_boxed_slice());
    let mut names: Vec<Name> = Vec::with_capacity(zone_count + links.len());
    for (zone, (rank, tags)) in zone_data.iter().zip(zone_meta) {
        names.push(Name {
            name: zone.name.clone(),
            rank,
            tags,
            zone,
        });
    }
    for link in links {
        let zone = hegel_internal_unwrap!(
            zone_data.iter().find(|zone| zone.name == link.primary),
            "tzdata link {} targets unknown zone {}",
            link.name,
            link.primary
        );
        hegel_internal_assert!(
            link.tags.contains(Tag::Link),
            "tzdata link {} lacks the link tag",
            link.name
        );
        names.push(Name {
            name: link.name,
            rank: link.rank,
            tags: link.tags,
            zone,
        });
    }
    names.sort_by(|a, b| a.name.cmp(&b.name));
    let mut seen_rank = alloc::vec![false; names.len()];
    for pair in names.windows(2) {
        hegel_internal_assert!(
            pair[0].name != pair[1].name,
            "tzdata name {} is listed twice",
            pair[0].name
        );
    }
    for name in &names {
        let slot = hegel_internal_unwrap!(
            seen_rank.get_mut(usize::from(name.rank)),
            "tzdata name {} has rank {} beyond the name count",
            name.name,
            name.rank
        );
        hegel_internal_assert!(!*slot, "tzdata rank {} is used twice", name.rank);
        *slot = true;
    }
    Ok(Table { version, names })
}

fn parse_zone_line(
    record: &mut ZoneRecord,
    kind: &str,
    fields: &[&str],
    lineno: usize,
) -> Result<(), InternalError> {
    let zone = &mut record.zone;
    match kind {
        "A" => {
            hegel_internal_assert!(
                zone.abbreviations.is_empty() && !fields.is_empty(),
                "tzdata line {lineno}: malformed abbreviation record"
            );
            zone.abbreviations = fields.iter().map(|s| s.to_string()).collect();
        }
        "I" => {
            hegel_internal_assert!(
                !record.has_initial && zone.transitions.is_empty() && zone.footer.is_none(),
                "tzdata line {lineno}: initial record repeated or out of order"
            );
            zone.initial = parse_type(zone, fields, lineno)?;
            record.has_initial = true;
        }
        "T" => {
            hegel_internal_assert!(
                fields.len() == 4,
                "tzdata line {lineno}: malformed transition record"
            );
            hegel_internal_assert!(
                zone.footer.is_none(),
                "tzdata line {lineno}: transition record after the footer"
            );
            let instant: i64 = parse_number(fields[0], lineno)?;
            hegel_internal_assert!(
                zone.transitions.last().is_none_or(|t| t.instant < instant),
                "tzdata line {lineno}: transitions are not ascending"
            );
            let kind = parse_type(zone, &fields[1..], lineno)?;
            zone.transitions.push(Transition { instant, kind });
        }
        "F" => {
            hegel_internal_assert!(
                zone.footer.is_none() && (fields.len() == 2 || fields.len() == 6),
                "tzdata line {lineno}: malformed footer record"
            );
            let standard = parse_footer_type(zone, &fields[..2], false, lineno)?;
            let dst = if fields.len() == 6 {
                Some(DstRule {
                    kind: parse_footer_type(zone, &fields[2..4], true, lineno)?,
                    start: parse_rule_date(fields[4], lineno)?,
                    end: parse_rule_date(fields[5], lineno)?,
                })
            } else {
                None
            };
            zone.footer = Some(Footer { standard, dst });
        }
        _ => hegel_internal_error!("tzdata line {lineno}: unknown record {kind:?}"),
    }
    Ok(())
}

fn parse_number<T: core::str::FromStr>(text: &str, lineno: usize) -> Result<T, InternalError> {
    Ok(hegel_internal_unwrap!(
        text.parse().ok(),
        "tzdata line {lineno}: bad number {text:?}"
    ))
}

fn parse_tags(text: &str, lineno: usize) -> Result<Tags, InternalError> {
    if text == "-" {
        return Ok(Tags::EMPTY);
    }
    let mut tags = Tags::EMPTY;
    for name in text.split(',') {
        let tag = hegel_internal_unwrap!(
            Tag::from_name(name),
            "tzdata line {lineno}: unknown tag {name:?}"
        );
        tags = tags.with(tag);
    }
    Ok(tags)
}

fn parse_abbreviation(zone: &Zone, text: &str, lineno: usize) -> Result<usize, InternalError> {
    let index: usize = parse_number(text, lineno)?;
    hegel_internal_assert!(
        index < zone.abbreviations.len(),
        "tzdata line {lineno}: abbreviation index {index} out of range"
    );
    Ok(index)
}

fn parse_utoff(text: &str, lineno: usize) -> Result<i32, InternalError> {
    let utoff: i32 = parse_number(text, lineno)?;
    hegel_internal_assert!(
        utoff.unsigned_abs() < UTOFF_BOUND.unsigned_abs(),
        "tzdata line {lineno}: offset {utoff} is not within {UTOFF_BOUND} seconds of UT"
    );
    Ok(utoff)
}

fn parse_type(zone: &Zone, fields: &[&str], lineno: usize) -> Result<LocalTimeType, InternalError> {
    hegel_internal_assert!(
        fields.len() == 3 && (fields[1] == "0" || fields[1] == "1"),
        "tzdata line {lineno}: malformed local time type"
    );
    Ok(LocalTimeType {
        utoff: parse_utoff(fields[0], lineno)?,
        is_dst: fields[1] == "1",
        abbreviation: parse_abbreviation(zone, fields[2], lineno)?,
    })
}

fn parse_footer_type(
    zone: &Zone,
    fields: &[&str],
    is_dst: bool,
    lineno: usize,
) -> Result<LocalTimeType, InternalError> {
    Ok(LocalTimeType {
        utoff: parse_utoff(fields[1], lineno)?,
        is_dst,
        abbreviation: parse_abbreviation(zone, fields[0], lineno)?,
    })
}

fn parse_rule_date(text: &str, lineno: usize) -> Result<RuleDate, InternalError> {
    let (day, time) = hegel_internal_unwrap!(
        text.split_once('/'),
        "tzdata line {lineno}: rule {text:?} has no time"
    );
    let time: i32 = parse_number(time, lineno)?;
    hegel_internal_assert!(
        (-167 * 3600..=167 * 3600).contains(&time),
        "tzdata line {lineno}: rule time {time} out of range"
    );
    let day = if let Some(julian) = day.strip_prefix('J') {
        let n: u16 = parse_number(julian, lineno)?;
        hegel_internal_assert!(
            (1..=365).contains(&n),
            "tzdata line {lineno}: Julian day {n} out of range"
        );
        RuleDay::Julian(n)
    } else if let Some(month_rule) = day.strip_prefix('M') {
        let parts = month_rule
            .split('.')
            .map(|part| parse_number::<u8>(part, lineno))
            .collect::<Result<Vec<u8>, InternalError>>()?;
        hegel_internal_assert!(
            parts.len() == 3
                && (1..=12).contains(&parts[0])
                && (1..=5).contains(&parts[1])
                && parts[2] <= 6,
            "tzdata line {lineno}: malformed month rule {day:?}"
        );
        RuleDay::MonthWeekDay {
            month: parts[0],
            week: parts[1],
            weekday: parts[2],
        }
    } else {
        let n: u16 = parse_number(day, lineno)?;
        hegel_internal_assert!(n <= 365, "tzdata line {lineno}: day {n} out of range");
        RuleDay::ZeroBased(n)
    };
    Ok(RuleDate { day, time })
}

